class Solution:
    def countValidWords(self, sentence: str) -> int:
        def valid(tok):
            hyphens = 0
            for i, ch in enumerate(tok):
                if ch.isdigit():
                    return False
                if ch == '-':
                    hyphens += 1
                    if hyphens > 1 or i == 0 or i == len(tok) - 1 \
                            or not tok[i - 1].islower() or not tok[i + 1].islower():
                        return False
                if ch in '!.,' and i != len(tok) - 1:
                    return False
            return True

        return sum(valid(t) for t in sentence.split())

