class Solution {
public:
    int countValidWords(string sentence) {
        int ans = 0;
        stringstream ss(sentence);
        string tok;
        while (ss >> tok) {
            bool ok = true;
            int hyphens = 0;
            for (int i = 0; i < (int)tok.size() && ok; ++i) {
                char ch = tok[i];
                if (isdigit(ch)) ok = false;
                else if (ch == '-') {
                    if (++hyphens > 1 || i == 0 || i == (int)tok.size() - 1
                        || !islower(tok[i - 1]) || !islower(tok[i + 1])) ok = false;
                } else if ((ch == '!' || ch == '.' || ch == ',')
                           && i != (int)tok.size() - 1) ok = false;
            }
            ans += ok;
        }
        return ans;
    }
};

