class Solution {
    public int countValidWords(String sentence) {
        int ans = 0;
        for (String tok : sentence.split("\\s+")) {
            if (tok.isEmpty()) continue;
            boolean ok = true;
            int hyphens = 0;
            for (int i = 0; i < tok.length() && ok; i++) {
                char ch = tok.charAt(i);
                if (Character.isDigit(ch)) ok = false;
                else if (ch == '-') {
                    if (++hyphens > 1 || i == 0 || i == tok.length() - 1
                        || !Character.isLowerCase(tok.charAt(i - 1))
                        || !Character.isLowerCase(tok.charAt(i + 1))) ok = false;
                } else if ((ch == '!' || ch == '.' || ch == ',')
                           && i != tok.length() - 1) ok = false;
            }
            if (ok) ans++;
        }
        return ans;
    }
}

