var countValidWords = function(sentence) {
    const valid = (tok) => {
        if (!tok.length) return false;
        let hyphens = 0;
        for (let i = 0; i < tok.length; i++) {
            const ch = tok[i];
            if (ch >= '0' && ch <= '9') return false;
            if (ch === '-') {
                if (++hyphens > 1 || i === 0 || i === tok.length - 1) return false;
                const prev = tok[i - 1], next = tok[i + 1];
                if (!(prev >= 'a' && prev <= 'z') || !(next >= 'a' && next <= 'z')) return false;
            }
            if ('!.,'.includes(ch) && i !== tok.length - 1) return false;
        }
        return true;
    };
    return sentence.split(/\s+/).filter(t => t && valid(t)).length;
};

