import java.util.regex.Pattern;

class Solution {
    public int countValidWords(String sentence) {
        Pattern pat = Pattern.compile("[a-z]+(-[a-z]+)?[!.,]?|[!.,]");
        int ans = 0;
        for (String tok : sentence.split("\\s+"))
            if (!tok.isEmpty() && pat.matcher(tok).matches()) ans++;
        return ans;
    }
}

